import type { LabImage } from "@/config/lab";

interface Props {
  image: LabImage;
  sizes: string;
  className?: string;
  priority?: boolean;
}

/** Responsive WebP image; below-the-fold images load lazily. */
export function Picture({ image, sizes, className = "", priority = false }: Props) {
  const srcSet = image.widths.map((w) => `${image.src}-${w}.webp ${w}w`).join(", ");
  const largest = image.widths.at(-1)!;
  return (
    // eslint-disable-next-line @next/next/no-img-element -- static export; srcset is generated by scripts/render
    <img
      src={`${image.src}-${largest}.webp`}
      srcSet={srcSet}
      sizes={sizes}
      width={largest}
      height={Math.round(largest / image.aspect)}
      alt={image.alt}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      decoding="async"
      className={className}
    />
  );
}
